        int len = bed.length;
        int planted = 0;
        for (int i = 0; i < len; i++) {
            if (bed[i] == 0) {
                boolean leftOk = (i == 0) || bed[i - 1] == 0;
                boolean rightOk = (i == len - 1) || bed[i + 1] == 0;
