import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;
        line = line.trim();
        if (line.isEmpty()) return;
        int[][] intervals = parsePairs(line);
        Arrays.sort(intervals, (a, b) -> Integer.compare(a[1], b[1]));
        int kept = 0;
        long lastEnd = Long.MIN_VALUE;
        for (int[] iv : intervals) {
            if (iv[0] >= lastEnd) {
                kept++;
                lastEnd = iv[1];
            }
        }
        System.out.println(intervals.length - kept);
    }

    static int[][] parsePairs(String s) {
        s = s.trim().replace(" ", "");
        if (s.startsWith("[")) s = s.substring(1);
        if (s.endsWith("]")) s = s.substring(0, s.length() - 1);
        if (s.isEmpty()) return new int[0][];
        String[] groups = s.split("\\],\\[");
        int[][] res = new int[groups.length][2];
        for (int i = 0; i < groups.length; i++) {
            String g = groups[i].replace("[", "").replace("]", "");
            String[] p = g.split(",");
            res[i][0] = Integer.parseInt(p[0].trim());
            res[i][1] = Integer.parseInt(p[1].trim());
        }
        return res;
    }
}

