import java.io.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;
        line = line.trim();
        if (line.isEmpty()) return;
        int sep = line.indexOf(';');
        int[] nums = parseIntArray(line.substring(0, sep));
        int k = Integer.parseInt(line.substring(sep + 1).trim());
        int lo = 0, hi = 0;
        for (int v : nums) {
            if (v > lo) lo = v;
            hi += v;
        }
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (canSplit(nums, mid, k)) hi = mid;
            else lo = mid + 1;
        }
        System.out.println(lo);
    }

    static boolean canSplit(int[] nums, int cap, int k) {
        int count = 1, sum = 0;
        for (int v : nums) {
            if (sum + v > cap) {
                count++;
                sum = v;
            } else {
                sum += v;
            }
        }
        return count <= k;
    }

    static int[] parseIntArray(String s) {
        s = s.trim();
        if (s.startsWith("[")) s = s.substring(1);
        if (s.endsWith("]")) s = s.substring(0, s.length() - 1);
        s = s.trim();
        if (s.isEmpty()) return new int[0];
        String[] parts = s.split(",");
        int[] a = new int[parts.length];
        for (int i = 0; i < parts.length; i++) a[i] = Integer.parseInt(parts[i].trim());
        return a;
    }
}
